119	void bm_dwmac_exit(struct platform_device *pdev, void *priv)
120	{
121		struct cvitek_mac *bsp_priv = priv;
122	
123		clk_disable_unprepare(bsp_priv->gate_clk_500m);
124		clk_disable_unprepare(bsp_priv->gate_clk_axi4);
125	}
