127	static int bm_dwmac_probe(struct platform_device *pdev)
128	{
129		struct plat_stmmacenet_data *plat_dat;
130		struct stmmac_resources stmmac_res;
131		struct cvitek_mac *bsp_priv = NULL;
132		int ret;
133	
134		pdev->dev.dma_mask = &bm_dma_mask;
135		pdev->dev.coherent_dma_mask = bm_dma_mask;
136	
137		bm_eth_reset_phy(pdev);
138	
139		ret = stmmac_get_platform_resources(pdev, &stmmac_res);
140		if (ret)
141			return ret;
142	
143		plat_dat = stmmac_probe_config_dt(pdev, &stmmac_res.mac);
144		if (IS_ERR(plat_dat))
145			return PTR_ERR(plat_dat);
146	
147		ret = stmmac_dvr_probe(&pdev->dev, plat_dat, &stmmac_res);
148		if (ret)
149			goto err_remove_config_dt;
150	
151		bsp_priv = devm_kzalloc(&pdev->dev, sizeof(*bsp_priv), GFP_KERNEL);
152		if (!bsp_priv)
153			return PTR_ERR(bsp_priv);
154	
155		bsp_priv->dev = &pdev->dev;
156	
157		/* clock setup */
158		bsp_priv->gate_clk_500m = devm_clk_get(&pdev->dev, "clk_500m_eth");
159	
160		if (IS_ERR(bsp_priv->gate_clk_500m))
161			dev_warn(&pdev->dev, "Cannot get clk_500m_eth!\n");
162		else
163			clk_prepare_enable(bsp_priv->gate_clk_500m);
164	
165		bsp_priv->gate_clk_axi4 = devm_clk_get(&pdev->dev, "clk_axi4_eth");
166	
167		if (IS_ERR(bsp_priv->gate_clk_axi4))
168			dev_warn(&pdev->dev, "Cannot get gate_clk_axi4!\n");
169		else
170			clk_prepare_enable(bsp_priv->gate_clk_axi4);
171	
172		plat_dat->bsp_priv = bsp_priv;
173		plat_dat->exit = bm_dwmac_exit;
174	
175		return 0;
176	
177	err_remove_config_dt:
178		stmmac_remove_config_dt(pdev, plat_dat);
179	
180		return ret;
181	}
