234	extern void stmmac_reset_subtask2(struct stmmac_priv *priv);
235	
236	static int cvi_eth_pm_resume(struct device *dev)
237	{
238		struct net_device *ndev = dev_get_drvdata(dev);
239		struct stmmac_priv *priv = netdev_priv(ndev);
240		struct platform_device *pdev = to_platform_device(dev);
241	
242		bm_eth_reset_phy(pdev);
243		writel(priv->reg_ctx->ctrl, priv->ioaddr + GMAC_CONTROL);
244		writel(priv->reg_ctx->frame_filter, priv->ioaddr + GMAC_FRAME_FILTER);
245		writel(priv->reg_ctx->hash_high, priv->ioaddr + GMAC_HASH_HIGH);
246		writel(priv->reg_ctx->hash_low, priv->ioaddr + GMAC_HASH_LOW);
247		writel(priv->reg_ctx->mii_addr, priv->ioaddr + GMAC_MII_ADDR);
248		writel(priv->reg_ctx->mii_data, priv->ioaddr + GMAC_MII_DATA);
249		writel(priv->reg_ctx->flow_ctrl, priv->ioaddr + GMAC_FLOW_CTRL);
250		writel(priv->reg_ctx->vlan_tag, priv->ioaddr + GMAC_VLAN_TAG);
251		writel(priv->reg_ctx->debug, priv->ioaddr + GMAC_DEBUG);
252		writel(priv->reg_ctx->wakeup_fileter, priv->ioaddr + GMAC_WAKEUP_FILTER);
253		writel(priv->reg_ctx->lpi_ctrl_status, priv->ioaddr + LPI_CTRL_STATUS);
254		writel(priv->reg_ctx->lpi_timer_ctrl, priv->ioaddr + LPI_TIMER_CTRL);
255		writel(priv->reg_ctx->int_mask, priv->ioaddr + GMAC_INT_MASK);
256		writel(priv->reg_ctx->mac_addr0_high, priv->ioaddr + GMAC_MAC_ADDR0_HIGH);
257		writel(priv->reg_ctx->mac_addr0_low, priv->ioaddr + GMAC_MAC_ADDR0_LOW);
258		writel(priv->reg_ctx->pcs_base, priv->ioaddr + GMAC_PCS_BASE);
259		writel(priv->reg_ctx->mmc_ctrl, priv->ioaddr + GMAC_MMC_CTRL);
260		writel(priv->reg_ctx->mmc_rx_intr_mask, priv->ioaddr + GMAC_MMC_RX_INTR_MASK);
261		writel(priv->reg_ctx->mmc_tx_intr_mask, priv->ioaddr + GMAC_MMC_TX_INTR_MASK);
262		writel(priv->reg_ctx->mmc_ipc_rx_intr_mask, priv->ioaddr + GMAC_MMC_IPC_RX_INTR_MASK);
263		writel(priv->reg_ctx->mmc_rx_csum_offload, priv->ioaddr + GMAC_MMC_RX_CSUM_OFFLOAD);
264		writel(priv->reg_ctx->dma_bus_mode | 0x1, priv->ioaddr + DMA_BUS_MODE);
265	
266		stmmac_reset_subtask2(priv);
267	
268		return 0;
269	}
