10	/* clock registers */
11	#define GMAC_CLK_CFG0	0x00
12	#define GMAC_CLK_CFG1	0x04
13	#define GMAC_CLK_CFG2	0x08
14	#define GMAC_CLK_CFG3	0x0C
15	#define GMAC_CLK_CFG4	0x10
16	#define GMAC_CLK_CFG5	0x14
17	#define GMAC_CLK_CFG6	0x18
18	
19	/* phy interface */
20	#define DWMAC_PHYIF_MII_GMII	0
21	#define DWMAC_PHYIF_RGMII	1
22	#define DWMAC_PHYIF_RMII	4
23	/* register bit fields, bit[3]: reserved, bit[2:0]: phy interface */
24	#define DWMAC_PHYIF_MASK	0x7
25	#define DWMAC_PHYIF_BIT_WIDTH	4
26	
27	/* TXCLK direction, 1:input, 0:output */
28	#define TXCLK_DIR_OUTPUT	0
29	#define TXCLK_DIR_INPUT		1
30	
31	#define GMAC_CLK_PLLOUT_250M	250000000
32	#define GMAC_GMII_RGMII_RATE	125000000
33	#define GMAC_MII_RATE		25000000
34	/* clock divider for speed */
35	#define GMAC_CLKDIV_125M	(GMAC_CLK_PLLOUT_250M / GMAC_GMII_RGMII_RATE)
36	#define GMAC_CLKDIV_25M		(GMAC_CLK_PLLOUT_250M / GMAC_MII_RATE)
37	
38	struct thead_dwmac_priv_data {
39		int id;
40		void __iomem *phy_if_reg;
41		void __iomem *txclk_dir_reg;
42		void __iomem *gmac_clk_reg;
43		phy_interface_t interface;
44		struct clk *gmac_pll_clk;
45		unsigned int gmac_pll_clk_freq;
46	};
