48	/* set GMAC PHY interface, 0:MII/GMII, 1:RGMII, 4:RMII */
49	static void thead_dwmac_set_phy_if(struct platform_device *pdev,
50					   void __iomem *phy_if_reg, int interface,
51					   int devid)
52	{
53		struct device *dev = &pdev->dev;
54		unsigned int phyif = PHY_INTERFACE_MODE_MII;
55		volatile uint32_t reg;
56	
57		if (phy_if_reg == NULL)
58			return;
59	
60		switch (interface)
61		{
62		case PHY_INTERFACE_MODE_MII:
63		case PHY_INTERFACE_MODE_GMII:
64			phyif = DWMAC_PHYIF_MII_GMII;
65			break;
66		case PHY_INTERFACE_MODE_RGMII:
67		case PHY_INTERFACE_MODE_RGMII_TXID:
68		case PHY_INTERFACE_MODE_RGMII_RXID:
69		case PHY_INTERFACE_MODE_RGMII_ID:
70			phyif = DWMAC_PHYIF_RGMII;
71			break;
72		case PHY_INTERFACE_MODE_RMII:
73			phyif = DWMAC_PHYIF_RMII;
74			break;
75		default:
76			dev_err(dev, "phy interface %d not supported\n", interface);
77			return;
78		};
79	
80		reg = readl(phy_if_reg);
81		reg &= ~(DWMAC_PHYIF_MASK << (DWMAC_PHYIF_BIT_WIDTH * devid));
82		reg |= (phyif & DWMAC_PHYIF_MASK) << (DWMAC_PHYIF_BIT_WIDTH * devid);
83		writel(reg, phy_if_reg);
84	}
