86	/*
87	 * set GMAC TXCLK direction
88	 *     MII        : TXCLK is input
89	 *     GMII/RGMII : TXCLK is output
90	 */
91	static void thead_dwmac_set_txclk_dir(struct platform_device *pdev,
92					void __iomem *txclk_dir_reg, int interface)
93	{
94		struct device *dev = &pdev->dev;
95		unsigned int txclk_dir = TXCLK_DIR_INPUT;
96	
97		if (txclk_dir_reg == NULL)
98			return;
99	
100		switch (interface)
101		{
102		case PHY_INTERFACE_MODE_MII:
103		case PHY_INTERFACE_MODE_RMII:
104			txclk_dir = TXCLK_DIR_INPUT;
105			break;
106		case PHY_INTERFACE_MODE_GMII:
107		case PHY_INTERFACE_MODE_RGMII:
108		case PHY_INTERFACE_MODE_RGMII_TXID:
109		case PHY_INTERFACE_MODE_RGMII_RXID:
110		case PHY_INTERFACE_MODE_RGMII_ID:
111			txclk_dir = TXCLK_DIR_OUTPUT;
112			break;
113		default:
114			dev_err(dev, "phy interface %d not supported\n", interface);
115			return;
116		};
117	
118		writel(txclk_dir, txclk_dir_reg);
119	}
