121	static void thead_dwmac_set_clk_source(struct platform_device *pdev,
122					void __iomem *gmac_clk_reg, int interface)
123	{
124		struct device *dev = &pdev->dev;
125		volatile uint32_t reg;
126	
127		if (gmac_clk_reg == NULL)
128			return;
129	
130		reg = readl(gmac_clk_reg + GMAC_CLK_CFG0);
131	
132		/* RX clock source */
133		reg |= BIT(7);  /* gmac_rx_clk_sel: extern pin */
134	
135		/* TX clock source */
136		if (interface == PHY_INTERFACE_MODE_MII) {
137			reg |= BIT(1);  /* gmac_tx_clk_sel: extern pin */
138			reg &= ~BIT(2); /* gmac_tx_clk_gbit_sel: u_tx_clk_mux */
139		} else if (interface == PHY_INTERFACE_MODE_GMII) {
140			reg &= ~BIT(5); /* gmac_tx_clk_out_sel: GMAC PLL */
141			reg |= BIT(2);  /* gmac_tx_clk_gbit_sel: GMAC PLL */
142		} else if (interface == PHY_INTERFACE_MODE_RGMII
143			|| interface == PHY_INTERFACE_MODE_RGMII_ID
144			|| interface == PHY_INTERFACE_MODE_RGMII_RXID
145			|| interface == PHY_INTERFACE_MODE_RGMII_TXID) {
146			reg &= ~BIT(5); /* gmac_tx_clk_out_sel: GMAC PLL */
147			reg |= BIT(2);  /* gmac_tx_clk_gbit_sel: GMAC PLL */
148		} else {
149			dev_err(dev, "phy interface %d not supported\n", interface);
150			return;
151		}
152	
153		writel(reg, gmac_clk_reg + GMAC_CLK_CFG0);
154	}
