157	/* set clock source */
158	static void thead_dwmac_set_clock_delay(struct platform_device *pdev,
159					void __iomem *gmac_clk_reg, int interface)
160	{
161		unsigned int delay;
162	
163		if (gmac_clk_reg == NULL)
164			return;
165	
166		if (of_property_read_u32(pdev->dev.of_node, "rx-clk-delay",
167					 &delay) == 0) {
168			/* RX clk delay */
169			writel(delay, gmac_clk_reg + GMAC_CLK_CFG1);
170			pr_info("RX clk delay: 0x%X\n", delay);
171		}
172	
173		if (of_property_read_u32(pdev->dev.of_node, "tx-clk-delay",
174					 &delay) == 0) {
175			/* TX clk delay */
176			writel(delay, gmac_clk_reg + GMAC_CLK_CFG2);
177			pr_info("TX clk delay: 0x%X\n", delay);
178		}
179	}
