181	/* set gmac pll divider (u_pll_clk_div) to get 250MHz clock */
182	static void thead_dwmac_set_pll_250M(void __iomem *gmac_clk_reg, int interface,
183					unsigned int src_freq)
184	{
185		volatile unsigned int reg;
186		unsigned int div = 1;
187	
188		if (gmac_clk_reg == NULL)
189			return;
190	
191		if (interface == PHY_INTERFACE_MODE_MII) {
192			/* For MII, no internal PLL is used */
193			return;
194		} else if (interface == PHY_INTERFACE_MODE_GMII
195			|| interface == PHY_INTERFACE_MODE_RGMII
196			|| interface == PHY_INTERFACE_MODE_RGMII_ID
197			|| interface == PHY_INTERFACE_MODE_RGMII_RXID
198			|| interface == PHY_INTERFACE_MODE_RGMII_TXID) {
199	
200			/* check clock */
201			if ((src_freq == 0) || (src_freq % GMAC_CLK_PLLOUT_250M != 0)) {
202				pr_err("error! invalid gmac pll freq %d\n", src_freq);
203				return;
204			}
205			div = src_freq / GMAC_CLK_PLLOUT_250M;
206	
207			/* disable pll_clk_div */
208			reg = readl(gmac_clk_reg + GMAC_CLK_CFG3);
209			reg &= ~BIT(31);
210			writel(reg, gmac_clk_reg + GMAC_CLK_CFG3);
211	
212			/* modify divider */
213			writel(div, gmac_clk_reg + GMAC_CLK_CFG3);
214	
215			/* enable pll_clk_div */
216			reg = readl(gmac_clk_reg + GMAC_CLK_CFG3);
217			reg |= BIT(31);
218			writel(reg, gmac_clk_reg + GMAC_CLK_CFG3);
219		} else {
220			pr_err("phy interface %d not supported\n", interface);
221			return;
222		}
223	}
224	
225	/* set gmac speed */
226	static void thead_dwmac_set_speed(void __iomem *gmac_clk_reg, int interface,
227					unsigned int speed)
228	{
229		volatile unsigned int reg;
230	
231		if (gmac_clk_reg == NULL)
232			return;
233	
234		if (interface == PHY_INTERFACE_MODE_MII) {
235			/* For MII, no internal PLL is used */
236			return;
237		} else if (interface == PHY_INTERFACE_MODE_GMII
238			|| interface == PHY_INTERFACE_MODE_RGMII
239			|| interface == PHY_INTERFACE_MODE_RGMII_ID
240			|| interface == PHY_INTERFACE_MODE_RGMII_RXID
241			|| interface == PHY_INTERFACE_MODE_RGMII_TXID) {
242	
243			/* disable gtx_clk_div */
244			reg = readl(gmac_clk_reg + GMAC_CLK_CFG4);
245			reg &= ~BIT(31);
246			writel(reg, gmac_clk_reg + GMAC_CLK_CFG4);
247	
248			/*
249			 * modify divider
250			 */
251			/* gtx_clk_div */
252			if (speed == SPEED_1000) {
253				writel(GMAC_CLKDIV_125M, gmac_clk_reg + GMAC_CLK_CFG4);
254			} else if (speed == SPEED_100) {
255				writel(GMAC_CLKDIV_25M, gmac_clk_reg + GMAC_CLK_CFG4);
256			} else {
257				writel(GMAC_CLKDIV_25M / 10, gmac_clk_reg + GMAC_CLK_CFG4);
258			}
259	
260			/* enable gtx_clk_div */
261			reg = readl(gmac_clk_reg + GMAC_CLK_CFG4);
262			reg |= BIT(31);
263			writel(reg, gmac_clk_reg + GMAC_CLK_CFG4);
264		} else {
265			pr_err("phy interface %d not supported\n", interface);
266			return;
267		}
268	}
