270	/* enable gmac clock */
271	static void thead_dwmac_enable_clock(struct platform_device *pdev,
272					void __iomem *gmac_clk_reg, int interface)
273	{
274		struct device *dev = &pdev->dev;
275		volatile unsigned int reg;
276	
277		if (gmac_clk_reg == NULL)
278			return;
279	
280		reg = readl(gmac_clk_reg + GMAC_CLK_CFG0);
281	
282		/* enable gmac_hclk */
283		reg |= BIT(14);
284	
285		if (interface == PHY_INTERFACE_MODE_MII) {
286			reg |= BIT(8);  /* enable gmac_rx_clk */
287			reg |= BIT(3);  /* enable gmac_tx_clk */
288		} else if (interface == PHY_INTERFACE_MODE_GMII) {
289			reg |= BIT(8);  /* enable gmac_rx_clk */
290			reg |= BIT(3);  /* enable gmac_tx_clk */
291			reg |= BIT(6);  /* enable gmac_tx_clk_out */
292		} else if (interface == PHY_INTERFACE_MODE_RGMII
293			|| interface == PHY_INTERFACE_MODE_RGMII_ID
294			|| interface == PHY_INTERFACE_MODE_RGMII_RXID
295			|| interface == PHY_INTERFACE_MODE_RGMII_TXID) {
296			reg |= BIT(8);  /* enable gmac_rx_clk */
297			reg |= BIT(3);  /* enable gmac_tx_clk */
298			reg |= BIT(6);  /* enable gmac_tx_clk_out */
299			reg |= BIT(9);  /* enable gmac_rx_clk_n */
300			reg |= BIT(4);  /* enable gmac_tx_clk_n */
301		} else {
302			dev_err(dev, "phy interface %d not supported\n", interface);
303			return;
304		}
305	
306		writel(reg, gmac_clk_reg + GMAC_CLK_CFG0);
307	}
