350	static int thead_dwmac_init(struct platform_device *pdev, void *bsp_priv)
351	{
352		struct thead_dwmac_priv_data *thead_plat_dat = bsp_priv;
353		struct device *dev = &pdev->dev;
354		struct device_node *np = pdev->dev.of_node;
355		struct resource *res;
356		void __iomem *ptr;
357		struct clk *clktmp;
358		int ret;
359	
360		thead_plat_dat->id = of_alias_get_id(np, "ethernet");
361		if (thead_plat_dat->id < 0) {
362			thead_plat_dat->id = 0;
363		}
364		dev_info(dev, "id: %d\n", thead_plat_dat->id);
365	
366		if (of_get_phy_mode(dev->of_node, &(thead_plat_dat->interface))) {
367			dev_err(dev, "of_get_phy_mode error\n");
368			return -1;
369		}
370	
371		dev_info(dev, "phy interface: %d\n", thead_plat_dat->interface);
372	
373		res = platform_get_resource_byname(pdev, IORESOURCE_MEM, "phy_if_reg");
374		if ((res != NULL) && (resource_type(res) == IORESOURCE_MEM)) {
375			ptr = devm_ioremap(dev, res->start, resource_size(res));
376			if (!ptr) {
377				dev_err(dev, "phy interface register not exist, skipped it\n");
378			} else {
379				thead_plat_dat->phy_if_reg = ptr;
380			}
381		}
382	
383		res = platform_get_resource_byname(pdev, IORESOURCE_MEM, "txclk_dir_reg");
384		ptr = devm_ioremap_resource(dev, res);
385		if (IS_ERR(ptr)) {
386			dev_err(dev, "txclk_dir register not exist, skipped it\n");
387		} else {
388			thead_plat_dat->txclk_dir_reg = ptr;
389		}
390	
391		res = platform_get_resource_byname(pdev, IORESOURCE_MEM, "clk_mgr_reg");
392		ptr = devm_ioremap_resource(dev, res);
393		if (IS_ERR(ptr)) {
394			dev_err(dev, "gmac_clk register not exist, skipped it\n");
395		} else {
396			thead_plat_dat->gmac_clk_reg = ptr;
397		}
398	
399		/* get gmac pll clk */
400		clktmp = devm_clk_get(dev, "gmac_pll_clk");
401		if (IS_ERR(clktmp)) {
402			dev_err(dev, "gmac_pll_clk not exist, skipped it\n");
403		} else {
404			thead_plat_dat->gmac_pll_clk = clktmp;
405	
406			ret = clk_prepare_enable(thead_plat_dat->gmac_pll_clk);
407			if (ret) {
408				dev_err(dev, "Failed to enable clk 'gmac_pll_clk'\n");
409				return -1;
410			}
411	
412			thead_plat_dat->gmac_pll_clk_freq =
413					clk_get_rate(thead_plat_dat->gmac_pll_clk);
414		}
415	
416		thead_dwmac_set_phy_if(pdev, thead_plat_dat->phy_if_reg,
417					thead_plat_dat->interface, thead_plat_dat->id);
418	
419		thead_dwmac_set_txclk_dir(pdev, thead_plat_dat->txclk_dir_reg,
420					thead_plat_dat->interface);
421	
422		thead_dwmac_set_clk_source(pdev, thead_plat_dat->gmac_clk_reg,
423					thead_plat_dat->interface);
424		thead_dwmac_set_clock_delay(pdev, thead_plat_dat->gmac_clk_reg,
425					thead_plat_dat->interface);
426	
427		thead_dwmac_set_pll_250M(thead_plat_dat->gmac_clk_reg,
428					thead_plat_dat->interface,
429					thead_plat_dat->gmac_pll_clk_freq);
430	
431		/* default speed is 1Gbps */
432		thead_dwmac_set_speed(thead_plat_dat->gmac_clk_reg,
433					thead_plat_dat->interface, SPEED_1000);
434	
435		thead_dwmac_enable_clock(pdev, thead_plat_dat->gmac_clk_reg,
436					thead_plat_dat->interface);
437		return 0;
438	}
