448	/**
449	 * dwmac1000_validate_mcast_bins - validates the number of Multicast filter bins
450	 * @mcast_bins: Multicast filtering bins
451	 * Description:
452	 * this function validates the number of Multicast filtering bins specified
453	 * by the configuration through the device tree. The Synopsys GMAC supports
454	 * 64 bins, 128 bins, or 256 bins. "bins" refer to the division of CRC
455	 * number space. 64 bins correspond to 6 bits of the CRC, 128 corresponds
456	 * to 7 bits, and 256 refers to 8 bits of the CRC. Any other setting is
457	 * invalid and will cause the filtering algorithm to use Multicast
458	 * promiscuous mode.
459	 */
460	static int dwmac1000_validate_mcast_bins(int mcast_bins)
461	{
462		int x = mcast_bins;
463	
464		switch (x) {
465		case HASH_TABLE_SIZE:
466		case 128:
467		case 256:
468			break;
469		default:
470			x = 0;
471			pr_info("Hash table entries set to unexpected value %d",
472				mcast_bins);
473			break;
474		}
475		return x;
476	}
477	
478	/**
479	 * dwmac1000_validate_ucast_entries - validate the Unicast address entries
480	 * @ucast_entries: number of Unicast address entries
481	 * Description:
482	 * This function validates the number of Unicast address entries supported
483	 * by a particular Synopsys 10/100/1000 controller. The Synopsys controller
484	 * supports 1..32, 64, or 128 Unicast filter entries for it's Unicast filter
485	 * logic. This function validates a valid, supported configuration is
486	 * selected, and defaults to 1 Unicast address if an unsupported
487	 * configuration is selected.
488	 */
489	static int dwmac1000_validate_ucast_entries(int ucast_entries)
490	{
491		int x = ucast_entries;
492	
493		switch (x) {
494		case 1 ... 32:
495		case 64:
496		case 128:
497			break;
498		default:
499			x = 1;
500			pr_info("Unicast table entries set to unexpected value %d\n",
501				ucast_entries);
502			break;
503		}
504		return x;
505	}
