2280	 * Some DMA parameters can be passed from the platform;
2281	 * in case of these are not passed a default is kept for the MAC or GMAC.
2282	 */
2283	static int stmmac_init_dma_engine(struct stmmac_priv *priv)
2284	{
2285		u32 rx_channels_count = priv->plat->rx_queues_to_use;
2286		u32 tx_channels_count = priv->plat->tx_queues_to_use;
2287		u32 dma_csr_ch = max(rx_channels_count, tx_channels_count);
2288		struct stmmac_rx_queue *rx_q;
2289		struct stmmac_tx_queue *tx_q;
2290		u32 chan = 0;
2291		int atds = 0;
2292		int ret = 0;
2293	
2294		if (!priv->plat->dma_cfg || !priv->plat->dma_cfg->pbl) {
2295			dev_err(priv->device, "Invalid DMA configuration\n");
2296			return -EINVAL;
2297		}
2298	
2299		if (priv->extend_desc && (priv->mode == STMMAC_RING_MODE))
2300			atds = 1;
2301	
2302		ret = stmmac_reset(priv, priv->ioaddr);
2303		if (ret) {
2304			dev_err(priv->device, "Failed to reset the dma\n");
2305			return ret;
2306		}
2307	
2308		/* DMA Configuration */
2309		stmmac_dma_init(priv, priv->ioaddr, priv->plat->dma_cfg, atds);
2310	
2311		if (priv->plat->axi)
2312			stmmac_axi(priv, priv->ioaddr, priv->plat->axi);
2313	
2314		/* DMA CSR Channel configuration */
2315		for (chan = 0; chan < dma_csr_ch; chan++)
2316			stmmac_init_chan(priv, priv->ioaddr, priv->plat->dma_cfg, chan);
2317	
2318		/* DMA RX Channel Configuration */
2319		for (chan = 0; chan < rx_channels_count; chan++) {
2320			rx_q = &priv->rx_queue[chan];
2321	
2322			stmmac_init_rx_chan(priv, priv->ioaddr, priv->plat->dma_cfg,
2323					    rx_q->dma_rx_phy, chan);
2324	
2325			rx_q->rx_tail_addr = rx_q->dma_rx_phy +
2326					     (priv->dma_rx_size *
2327					      sizeof(struct dma_desc));
2328			stmmac_set_rx_tail_ptr(priv, priv->ioaddr,
2329					       rx_q->rx_tail_addr, chan);
2330		}
2331	
2332		/* DMA TX Channel Configuration */
2333		for (chan = 0; chan < tx_channels_count; chan++) {
2334			tx_q = &priv->tx_queue[chan];
2335	
2336			stmmac_init_tx_chan(priv, priv->ioaddr, priv->plat->dma_cfg,
2337					    tx_q->dma_tx_phy, chan);
2338	
2339			tx_q->tx_tail_addr = tx_q->dma_tx_phy;
2340			stmmac_set_tx_tail_ptr(priv, priv->ioaddr,
2341					       tx_q->tx_tail_addr, chan);
2342		}
2343	
2344		return ret;
2345	}
