1960	 * stmmac_tx_clean - to manage the transmission completion
1961	 * @priv: driver private structure
1962	 * @budget: napi budget limiting this functions packet handling
1963	 * @queue: TX queue index
1964	 * Description: it reclaims the transmit resources after transmission completes.
1965	 */
1966	static int stmmac_tx_clean(struct stmmac_priv *priv, int budget, u32 queue)
1967	{
1968		struct stmmac_tx_queue *tx_q = &priv->tx_queue[queue];
1969		unsigned int bytes_compl = 0, pkts_compl = 0;
1970		unsigned int entry, count = 0;
1971	
1972		__netif_tx_lock_bh(netdev_get_tx_queue(priv->dev, queue));
1973	
1974		priv->xstats.tx_clean++;
1975	
1976		entry = tx_q->dirty_tx;
1977		while ((entry != tx_q->cur_tx) && (count < budget)) {
1978			struct sk_buff *skb = tx_q->tx_skbuff[entry];
1979			struct dma_desc *p;
1980			int status;
1981	
1982			if (priv->extend_desc)
1983				p = (struct dma_desc *)(tx_q->dma_etx + entry);
1984			else if (tx_q->tbs & STMMAC_TBS_AVAIL)
1985				p = &tx_q->dma_entx[entry].basic;
1986			else
1987				p = tx_q->dma_tx + entry;
1988	
1989			status = stmmac_tx_status(priv, &priv->dev->stats,
1990					&priv->xstats, p, priv->ioaddr);
1991			/* Check if the descriptor is owned by the DMA */
1992			if (unlikely(status & tx_dma_own))
1993				break;
1994	
1995			count++;
1996	
1997			/* Make sure descriptor fields are read after reading
1998			 * the own bit.
1999			 */
2000			dma_rmb();
2001	
2002			/* Just consider the last segment and ...*/
2003			if (likely(!(status & tx_not_ls))) {
2004				/* ... verify the status error condition */
2005				if (unlikely(status & tx_err)) {
2006					priv->dev->stats.tx_errors++;
2007				} else {
2008					priv->dev->stats.tx_packets++;
2009					priv->xstats.tx_pkt_n++;
2010				}
2011				stmmac_get_tx_hwtstamp(priv, p, skb);
2012			}
2013	
2014			if (likely(tx_q->tx_skbuff_dma[entry].buf)) {
2015				if (tx_q->tx_skbuff_dma[entry].map_as_page)
2016					dma_unmap_page(priv->device,
2017						       tx_q->tx_skbuff_dma[entry].buf,
2018						       tx_q->tx_skbuff_dma[entry].len,
2019						       DMA_TO_DEVICE);
2020				else
2021					dma_unmap_single(priv->device,
2022							 tx_q->tx_skbuff_dma[entry].buf,
2023							 tx_q->tx_skbuff_dma[entry].len,
2024							 DMA_TO_DEVICE);
2025				tx_q->tx_skbuff_dma[entry].buf = 0;
2026				tx_q->tx_skbuff_dma[entry].len = 0;
2027				tx_q->tx_skbuff_dma[entry].map_as_page = false;
2028			}
2029	
2030			stmmac_clean_desc3(priv, tx_q, p);
2031	
2032			tx_q->tx_skbuff_dma[entry].last_segment = false;
2033			tx_q->tx_skbuff_dma[entry].is_jumbo = false;
2034	
2035			if (likely(skb != NULL)) {
2036				pkts_compl++;
2037				bytes_compl += skb->len;
2038				dev_consume_skb_any(skb);
2039				tx_q->tx_skbuff[entry] = NULL;
2040			}
2041	
2042			stmmac_release_tx_desc(priv, p, priv->mode);
2043	
2044			entry = STMMAC_GET_ENTRY(entry, priv->dma_tx_size);
2045		}
2046		tx_q->dirty_tx = entry;
2047	
2048		netdev_tx_completed_queue(netdev_get_tx_queue(priv->dev, queue),
2049					  pkts_compl, bytes_compl);
2050	
2051		if (unlikely(netif_tx_queue_stopped(netdev_get_tx_queue(priv->dev,
2052									queue))) &&
2053		    stmmac_tx_avail(priv, queue) > STMMAC_TX_THRESH(priv)) {
2054	
2055			netif_dbg(priv, tx_done, priv->dev,
2056				  "%s: restart transmit\n", __func__);
2057			netif_tx_wake_queue(netdev_get_tx_queue(priv->dev, queue));
2058		}
2059	
2060		if ((priv->eee_enabled) && (!priv->tx_path_in_lpi_mode)) {
2061			stmmac_enable_eee_mode(priv);
2062			mod_timer(&priv->eee_ctrl_timer, STMMAC_LPI_T(priv->tx_lpi_timer));
2063		}
2064	
2065		/* We still have pending packets, let's call for a new scheduling */
2066		if (tx_q->dirty_tx != tx_q->cur_tx)
2067			mod_timer(&tx_q->txtimer, STMMAC_COAL_TIMER(priv->tx_coal_timer));
2068	
2069		__netif_tx_unlock_bh(netdev_get_tx_queue(priv->dev, queue));
2070	
2071		return count;
2072	}
