2617	 * stmmac_hw_setup - setup mac in a usable state.
2618	 *  @dev : pointer to the device structure.
2619	 *  @init_ptp: initialize PTP if set
2620	 *  Description:
2621	 *  this is the main function to setup the HW in a usable state because the
2622	 *  dma engine is reset, the core registers are configured (e.g. AXI,
2623	 *  Checksum features, timers). The DMA is ready to start receiving and
2624	 *  transmitting.
2625	 *  Return value:
2626	 *  0 on success and an appropriate (-)ve integer as defined in errno.h
2627	 *  file on failure.
2628	 */
2629	static int stmmac_hw_setup(struct net_device *dev, bool init_ptp)
2630	{
2631		struct stmmac_priv *priv = netdev_priv(dev);
2632		u32 rx_cnt = priv->plat->rx_queues_to_use;
2633		u32 tx_cnt = priv->plat->tx_queues_to_use;
2634		u32 chan;
2635		int ret;
2636	
2637		/* DMA initialization and SW reset */
2638		ret = stmmac_init_dma_engine(priv);
2639		if (ret < 0) {
2640			netdev_err(priv->dev, "%s: DMA engine initialization failed\n",
2641				   __func__);
2642			return ret;
2643		}
2644	
2645		/* Copy the MAC addr into the HW  */
2646		stmmac_set_umac_addr(priv, priv->hw, dev->dev_addr, 0);
2647	
2648		/* PS and related bits will be programmed according to the speed */
2649		if (priv->hw->pcs) {
2650			int speed = priv->plat->mac_port_sel_speed;
2651	
2652			if ((speed == SPEED_10) || (speed == SPEED_100) ||
2653			    (speed == SPEED_1000)) {
2654				priv->hw->ps = speed;
2655			} else {
2656				dev_warn(priv->device, "invalid port speed\n");
2657				priv->hw->ps = 0;
2658			}
2659		}
2660	
2661		/* Initialize the MAC Core */
2662		stmmac_core_init(priv, priv->hw, dev);
2663	
2664		/* Initialize MTL*/
2665		stmmac_mtl_configuration(priv);
2666	
2667		/* Initialize Safety Features */
2668		stmmac_safety_feat_configuration(priv);
2669	
2670		ret = stmmac_rx_ipc(priv, priv->hw);
2671		if (!ret) {
2672			netdev_warn(priv->dev, "RX IPC Checksum Offload disabled\n");
2673			priv->plat->rx_coe = STMMAC_RX_COE_NONE;
2674			priv->hw->rx_csum = 0;
2675		}
2676	
2677		/* Enable the MAC Rx/Tx */
2678		stmmac_mac_set(priv, priv->ioaddr, true);
2679	
2680		/* Set the HW DMA mode and the COE */
2681		stmmac_dma_operation_mode(priv);
2682	
2683		stmmac_mmc_setup(priv);
2684	
2685		if (init_ptp) {
2686			ret = clk_prepare_enable(priv->plat->clk_ptp_ref);
2687			if (ret < 0)
2688				netdev_warn(priv->dev, "failed to enable PTP reference clock: %d\n", ret);
2689	
2690			ret = stmmac_init_ptp(priv);
2691			if (ret == -EOPNOTSUPP)
2692				netdev_warn(priv->dev, "PTP not supported by HW\n");
2693			else if (ret)
2694				netdev_warn(priv->dev, "PTP init failed\n");
2695		}
2696	
2697		priv->eee_tw_timer = STMMAC_DEFAULT_TWT_LS;
2698	
2699		/* Convert the timer from msec to usec */
2700		if (!priv->tx_lpi_timer)
2701			priv->tx_lpi_timer = eee_timer * 1000;
2702	
2703		if (priv->use_riwt) {
2704			if (!priv->rx_riwt)
2705				priv->rx_riwt = DEF_DMA_RIWT;
2706	
2707			ret = stmmac_rx_watchdog(priv, priv->ioaddr, priv->rx_riwt, rx_cnt);
2708		}
2709	
2710		if (priv->hw->pcs)
2711			stmmac_pcs_ctrl_ane(priv, priv->ioaddr, 1, priv->hw->ps, 0);
2712	
2713		/* set TX and RX rings length */
2714		stmmac_set_rings_length(priv);
2715	
2716		/* Enable TSO */
2717		if (priv->tso) {
2718			for (chan = 0; chan < tx_cnt; chan++)
2719				stmmac_enable_tso(priv, priv->ioaddr, 1, chan);
2720		}
2721	
2722		/* Enable Split Header */
2723		if (priv->sph && priv->hw->rx_csum) {
2724			for (chan = 0; chan < rx_cnt; chan++)
2725				stmmac_enable_sph(priv, priv->ioaddr, 1, chan);
2726		}
2727	
2728		/* VLAN Tag Insertion */
2729		if (priv->dma_cap.vlins)
2730			stmmac_enable_vlan(priv, priv->hw, STMMAC_VLAN_INSERT);
2731	
2732		/* TBS */
2733		for (chan = 0; chan < tx_cnt; chan++) {
2734			struct stmmac_tx_queue *tx_q = &priv->tx_queue[chan];
2735			int enable = tx_q->tbs & STMMAC_TBS_AVAIL;
2736	
2737			stmmac_enable_tbs(priv, priv->ioaddr, enable, chan);
2738		}
2739	
2740		/* Configure real RX and TX queues */
2741		netif_set_real_num_rx_queues(dev, priv->plat->rx_queues_to_use);
2742		netif_set_real_num_tx_queues(dev, priv->plat->tx_queues_to_use);
2743	
2744		/* Start the ball rolling... */
2745		stmmac_start_all_dma(priv);
2746	
2747		return 0;
2748	}
