2766	static int stmmac_open(struct net_device *dev)
2767	{
2768		struct stmmac_priv *priv = netdev_priv(dev);
2769		int bfsize = 0;
2770		u32 chan;
2771		int ret;
2772	
2773		if (priv->hw->pcs != STMMAC_PCS_TBI &&
2774		    priv->hw->pcs != STMMAC_PCS_RTBI &&
2775		    priv->hw->xpcs == NULL) {
2776			ret = stmmac_init_phy(dev);
2777			if (ret) {
2778				netdev_err(priv->dev,
2779					   "%s: Cannot attach to PHY (error: %d)\n",
2780					   __func__, ret);
2781				return ret;
2782			}
2783		}
2784	
2785		/* Extra statistics */
2786		memset(&priv->xstats, 0, sizeof(struct stmmac_extra_stats));
2787		priv->xstats.threshold = tc;
2788	
2789		bfsize = stmmac_set_16kib_bfsize(priv, dev->mtu);
2790		if (bfsize < 0)
2791			bfsize = 0;
2792	
2793		if (bfsize < BUF_SIZE_16KiB)
2794			bfsize = stmmac_set_bfsize(dev->mtu, priv->dma_buf_sz);
2795	
2796		priv->dma_buf_sz = bfsize;
2797		buf_sz = bfsize;
2798	
2799		priv->rx_copybreak = STMMAC_RX_COPYBREAK;
2800	
2801		if (!priv->dma_tx_size)
2802			priv->dma_tx_size = DMA_DEFAULT_TX_SIZE;
2803		if (!priv->dma_rx_size)
2804			priv->dma_rx_size = DMA_DEFAULT_RX_SIZE;
2805	
2806		/* Earlier check for TBS */
2807		for (chan = 0; chan < priv->plat->tx_queues_to_use; chan++) {
2808			struct stmmac_tx_queue *tx_q = &priv->tx_queue[chan];
2809			int tbs_en = priv->plat->tx_queues_cfg[chan].tbs_en;
2810	
2811			tx_q->tbs |= tbs_en ? STMMAC_TBS_AVAIL : 0;
2812			if (stmmac_enable_tbs(priv, priv->ioaddr, tbs_en, chan))
2813				tx_q->tbs &= ~STMMAC_TBS_AVAIL;
2814		}
2815	
2816		ret = alloc_dma_desc_resources(priv);
2817		if (ret < 0) {
2818			netdev_err(priv->dev, "%s: DMA descriptors allocation failed\n",
2819				   __func__);
2820			goto dma_desc_error;
2821		}
2822	
2823		ret = init_dma_desc_rings(dev, GFP_KERNEL);
2824		if (ret < 0) {
2825			netdev_err(priv->dev, "%s: DMA descriptors initialization failed\n",
2826				   __func__);
2827			goto init_error;
2828		}
2829	
2830		ret = stmmac_hw_setup(dev, true);
2831		if (ret < 0) {
2832			netdev_err(priv->dev, "%s: Hw setup failed\n", __func__);
2833			goto init_error;
2834		}
2835	
2836		stmmac_init_coalesce(priv);
2837	
2838		phylink_start(priv->phylink);
2839		/* We may have called phylink_speed_down before */
2840		phylink_speed_up(priv->phylink);
2841	
2842		/* Request the IRQ lines */
2843		ret = request_irq(dev->irq, stmmac_interrupt,
2844				  IRQF_SHARED, dev->name, dev);
2845		if (unlikely(ret < 0)) {
2846			netdev_err(priv->dev,
2847				   "%s: ERROR: allocating the IRQ %d (error: %d)\n",
2848				   __func__, dev->irq, ret);
2849			goto irq_error;
2850		}
2851	
2852		/* Request the Wake IRQ in case of another line is used for WoL */
2853		if (priv->wol_irq != dev->irq) {
2854			ret = request_irq(priv->wol_irq, stmmac_interrupt,
2855					  IRQF_SHARED, dev->name, dev);
2856			if (unlikely(ret < 0)) {
2857				netdev_err(priv->dev,
2858					   "%s: ERROR: allocating the WoL IRQ %d (%d)\n",
2859					   __func__, priv->wol_irq, ret);
2860				goto wolirq_error;
2861			}
2862		}
2863	
2864		/* Request the IRQ lines */
2865		if (priv->lpi_irq > 0) {
2866			ret = request_irq(priv->lpi_irq, stmmac_interrupt, IRQF_SHARED,
2867					  dev->name, dev);
2868			if (unlikely(ret < 0)) {
2869				netdev_err(priv->dev,
2870					   "%s: ERROR: allocating the LPI IRQ %d (%d)\n",
2871					   __func__, priv->lpi_irq, ret);
2872				goto lpiirq_error;
2873			}
2874		}
2875	
2876		stmmac_enable_all_queues(priv);
2877		netif_tx_start_all_queues(priv->dev);
2878	
2879		return 0;
2880	
2881	lpiirq_error:
2882		if (priv->wol_irq != dev->irq)
2883			free_irq(priv->wol_irq, dev);
2884	wolirq_error:
2885		free_irq(dev->irq, dev);
2886	irq_error:
2887		phylink_stop(priv->phylink);
2888	
2889		for (chan = 0; chan < priv->plat->tx_queues_to_use; chan++)
2890			del_timer_sync(&priv->tx_queue[chan].txtimer);
2891	
2892		stmmac_hw_teardown(dev);
2893	init_error:
2894		free_dma_desc_resources(priv);
2895	dma_desc_error:
2896		phylink_disconnect_phy(priv->phylink);
2897		return ret;
2898	}
