3298	 *  stmmac_xmit - Tx entry point of the driver
3299	 *  @skb : the socket buffer
3300	 *  @dev : device pointer
3301	 *  Description : this is the tx entry point of the driver.
3302	 *  It programs the chain or the ring and supports oversized frames
3303	 *  and SG feature.
3304	 */
3305	static netdev_tx_t stmmac_xmit(struct sk_buff *skb, struct net_device *dev)
3306	{
3307		unsigned int first_entry, tx_packets, enh_desc;
3308		struct stmmac_priv *priv = netdev_priv(dev);
3309		unsigned int nopaged_len = skb_headlen(skb);
3310		int i, csum_insertion = 0, is_jumbo = 0;
3311		u32 queue = skb_get_queue_mapping(skb);
3312		int nfrags = skb_shinfo(skb)->nr_frags;
3313		int gso = skb_shinfo(skb)->gso_type;
3314		struct dma_edesc *tbs_desc = NULL;
3315		int entry, desc_size, first_tx;
3316		struct dma_desc *desc, *first;
3317		struct stmmac_tx_queue *tx_q;
3318		bool has_vlan, set_ic;
3319		dma_addr_t des;
3320	
3321		tx_q = &priv->tx_queue[queue];
3322		first_tx = tx_q->cur_tx;
3323	
3324		if (priv->tx_path_in_lpi_mode)
3325			stmmac_disable_eee_mode(priv);
3326	
3327		/* Manage oversized TCP frames for GMAC4 device */
3328		if (skb_is_gso(skb) && priv->tso) {
3329			if (gso & (SKB_GSO_TCPV4 | SKB_GSO_TCPV6))
3330				return stmmac_tso_xmit(skb, dev);
3331			if (priv->plat->has_gmac4 && (gso & SKB_GSO_UDP_L4))
3332				return stmmac_tso_xmit(skb, dev);
3333		}
3334	
3335		if (unlikely(stmmac_tx_avail(priv, queue) < nfrags + 1)) {
3336			if (!netif_tx_queue_stopped(netdev_get_tx_queue(dev, queue))) {
3337				netif_tx_stop_queue(netdev_get_tx_queue(priv->dev,
3338									queue));
3339				/* This is a hard error, log it. */
3340				netdev_err(priv->dev,
3341					   "%s: Tx Ring full when queue awake\n",
3342					   __func__);
3343			}
3344			return NETDEV_TX_BUSY;
3345		}
3346	
3347		/* Check if VLAN can be inserted by HW */
3348		has_vlan = stmmac_vlan_insert(priv, skb, tx_q);
3349	
3350		entry = tx_q->cur_tx;
3351		first_entry = entry;
3352		WARN_ON(tx_q->tx_skbuff[first_entry]);
3353	
3354		csum_insertion = (skb->ip_summed == CHECKSUM_PARTIAL);
3355	
3356		if (likely(priv->extend_desc))
3357			desc = (struct dma_desc *)(tx_q->dma_etx + entry);
3358		else if (tx_q->tbs & STMMAC_TBS_AVAIL)
3359			desc = &tx_q->dma_entx[entry].basic;
3360		else
3361			desc = tx_q->dma_tx + entry;
3362	
3363		first = desc;
3364	
3365		if (has_vlan)
3366			stmmac_set_desc_vlan(priv, first, STMMAC_VLAN_INSERT);
3367	
3368		enh_desc = priv->plat->enh_desc;
3369		/* To program the descriptors according to the size of the frame */
3370		if (enh_desc)
3371			is_jumbo = stmmac_is_jumbo_frm(priv, skb->len, enh_desc);
3372	
3373		if (unlikely(is_jumbo)) {
3374			entry = stmmac_jumbo_frm(priv, tx_q, skb, csum_insertion);
3375			if (unlikely(entry < 0) && (entry != -EINVAL))
3376				goto dma_map_err;
3377		}
3378	
3379		for (i = 0; i < nfrags; i++) {
3380			const skb_frag_t *frag = &skb_shinfo(skb)->frags[i];
3381			int len = skb_frag_size(frag);
3382			bool last_segment = (i == (nfrags - 1));
3383	
3384			entry = STMMAC_GET_ENTRY(entry, priv->dma_tx_size);
3385			WARN_ON(tx_q->tx_skbuff[entry]);
3386	
3387			if (likely(priv->extend_desc))
3388				desc = (struct dma_desc *)(tx_q->dma_etx + entry);
3389			else if (tx_q->tbs & STMMAC_TBS_AVAIL)
3390				desc = &tx_q->dma_entx[entry].basic;
3391			else
3392				desc = tx_q->dma_tx + entry;
3393	
3394			des = skb_frag_dma_map(priv->device, frag, 0, len,
3395					       DMA_TO_DEVICE);
3396			if (dma_mapping_error(priv->device, des))
3397				goto dma_map_err; /* should reuse desc w/o issues */
3398	
3399			tx_q->tx_skbuff_dma[entry].buf = des;
3400	
3401			stmmac_set_desc_addr(priv, desc, des);
3402	
3403			tx_q->tx_skbuff_dma[entry].map_as_page = true;
3404			tx_q->tx_skbuff_dma[entry].len = len;
3405			tx_q->tx_skbuff_dma[entry].last_segment = last_segment;
3406	
3407			/* Prepare the descriptor and set the own bit too */
3408			stmmac_prepare_tx_desc(priv, desc, 0, len, csum_insertion,
3409					priv->mode, 1, last_segment, skb->len);
3410		}
3411	
3412		/* Only the last descriptor gets to point to the skb. */
3413		tx_q->tx_skbuff[entry] = skb;
3414	
3415		/* According to the coalesce parameter the IC bit for the latest
3416		 * segment is reset and the timer re-started to clean the tx status.
3417		 * This approach takes care about the fragments: desc is the first
3418		 * element in case of no SG.
3419		 */
3420		tx_packets = (entry + 1) - first_tx;
3421		tx_q->tx_count_frames += tx_packets;
3422	
3423		if ((skb_shinfo(skb)->tx_flags & SKBTX_HW_TSTAMP) && priv->hwts_tx_en)
3424			set_ic = true;
3425		else if (!priv->tx_coal_frames)
3426			set_ic = false;
3427		else if (tx_packets > priv->tx_coal_frames)
3428			set_ic = true;
3429		else if ((tx_q->tx_count_frames % priv->tx_coal_frames) < tx_packets)
3430			set_ic = true;
3431		else
3432			set_ic = false;
3433	
3434		if (set_ic) {
3435			if (likely(priv->extend_desc))
3436				desc = &tx_q->dma_etx[entry].basic;
3437			else if (tx_q->tbs & STMMAC_TBS_AVAIL)
3438				desc = &tx_q->dma_entx[entry].basic;
3439			else
3440				desc = &tx_q->dma_tx[entry];
3441	
3442			tx_q->tx_count_frames = 0;
3443			stmmac_set_tx_ic(priv, desc);
3444			priv->xstats.tx_set_ic_bit++;
3445		}
3446	
3447		/* We've used all descriptors we need for this skb, however,
3448		 * advance cur_tx so that it references a fresh descriptor.
3449		 * ndo_start_xmit will fill this descriptor the next time it's
3450		 * called and stmmac_tx_clean may clean up to this descriptor.
3451		 */
3452		entry = STMMAC_GET_ENTRY(entry, priv->dma_tx_size);
3453		tx_q->cur_tx = entry;
3454	
3455		if (netif_msg_pktdata(priv)) {
3456			netdev_dbg(priv->dev,
3457				   "%s: curr=%d dirty=%d f=%d, e=%d, first=%p, nfrags=%d",

3906	static int stmmac_napi_poll_rx(struct napi_struct *napi, int budget)
3907	{
3908		struct stmmac_channel *ch =
3909			container_of(napi, struct stmmac_channel, rx_napi);
3910		struct stmmac_priv *priv = ch->priv_data;
3911		u32 chan = ch->index;
3912		int work_done;
3913	
3914		priv->xstats.napi_poll++;
3915	
3916		work_done = stmmac_rx(priv, budget, chan);
3917		if (work_done < budget && napi_complete_done(napi, work_done)) {
3918			unsigned long flags;
3919	
3920			spin_lock_irqsave(&ch->lock, flags);
3921			stmmac_enable_dma_irq(priv, priv->ioaddr, chan, 1, 0);
3922			spin_unlock_irqrestore(&ch->lock, flags);
3923		}
3924	
3925		return work_done;
3926	}
