1549	/**
1550	 * free_dma_rx_desc_resources - free RX dma desc resources
1551	 * @priv: private structure
1552	 */
1553	static void free_dma_rx_desc_resources(struct stmmac_priv *priv)
1554	{
1555		u32 rx_count = priv->plat->rx_queues_to_use;
1556		u32 queue;
1557	
1558		/* Free RX queue resources */
1559		for (queue = 0; queue < rx_count; queue++) {
1560			struct stmmac_rx_queue *rx_q = &priv->rx_queue[queue];
1561	
1562			/* Release the DMA RX socket buffers */
1563			dma_free_rx_skbufs(priv, queue);
1564	
1565			/* Free DMA regions of consistent memory previously allocated */
1566			if (!priv->extend_desc)
1567				dma_free_coherent(priv->device, priv->dma_rx_size *
1568						  sizeof(struct dma_desc),
1569						  rx_q->dma_rx, rx_q->dma_rx_phy);
1570			else
1571				dma_free_coherent(priv->device, priv->dma_rx_size *
1572						  sizeof(struct dma_extended_desc),
1573						  rx_q->dma_erx, rx_q->dma_rx_phy);
1574	
1575			kfree(rx_q->buf_pool);
1576			if (rx_q->page_pool)
1577				page_pool_destroy(rx_q->page_pool);
1578		}
1579	}
