1581	/**
1582	 * free_dma_tx_desc_resources - free TX dma desc resources
1583	 * @priv: private structure
1584	 */
1585	static void free_dma_tx_desc_resources(struct stmmac_priv *priv)
1586	{
1587		u32 tx_count = priv->plat->tx_queues_to_use;
1588		u32 queue;
1589	
1590		/* Free TX queue resources */
1591		for (queue = 0; queue < tx_count; queue++) {
1592			struct stmmac_tx_queue *tx_q = &priv->tx_queue[queue];
1593			size_t size;
1594			void *addr;
1595	
1596			/* Release the DMA TX socket buffers */
1597			dma_free_tx_skbufs(priv, queue);
1598	
1599			if (priv->extend_desc) {
1600				size = sizeof(struct dma_extended_desc);
1601				addr = tx_q->dma_etx;
1602			} else if (tx_q->tbs & STMMAC_TBS_AVAIL) {
1603				size = sizeof(struct dma_edesc);
1604				addr = tx_q->dma_entx;
1605			} else {
1606				size = sizeof(struct dma_desc);
1607				addr = tx_q->dma_tx;
1608			}
1609	
1610			size *= priv->dma_tx_size;
1611	
1612			dma_free_coherent(priv->device, size, addr, tx_q->dma_tx_phy);
