68	static inline void ndesc_end_tx_desc_on_ring(struct dma_desc *p, int end)
69	{
70		if (end)
71			p->des1 |= cpu_to_le32(TDES1_END_RING);
72		else
73			p->des1 &= cpu_to_le32(~TDES1_END_RING);
74	}
