    return tx_dma_own;               // DMA 还在用

// 只有 LAST_SEGMENT 的帧才算完整
if (likely(!(tdes1 & TDES1_LAST_SEGMENT)))
    return tx_not_ls;

// 错误汇总检查
if (unlikely(tdes0 & TDES0_ERROR_SUMMARY)) {
    if (unlikely(tdes0 & TDES0_UNDERFLOW_ERROR)) {   // bit 1
        x->tx_underflow++;
        stats->tx_fifo_errors++;
    }
    if (unlikely(tdes0 & TDES0_NO_CARRIER)) {        // bit 10
        ...
    }
    ...
    ret = tx_err;
}
```

